diff --git a/src/type1/t1parse.c b/src/type1/t1parse.c
index 8b4809f..2056c02 100644
--- a/src/type1/t1parse.c
+++ b/src/type1/t1parse.c
@@ -283,7 +283,7 @@
         if ( error )
           goto Fail;

-        if ( tag != 0x8002U )
+        if ( tag != 0x8002U || !size )
           break;

         parser->private_len += size;

diff --git a/src/type1/t1parse.c b/src/type1/t1parse.c
index 6947b3d..7dc5d74 100644
--- a/src/type1/t1parse.c
+++ b/src/type1/t1parse.c
@@ -269,30 +269,31 @@
     if ( parser->in_pfb )
     {
       /* in the case of the PFB format, the private dictionary can be */
-      /* made of several adjacent segments.                           */
+      /* made of several adjacent segments.  We thus first scan the   */
+      /* segments to compute the total size of the private dictionary */
+      /* then read them one by one into a single block.               */
+      FT_ULong   start_pos = FT_STREAM_POS();
       FT_UShort  tag;
-      FT_Byte*   priv_dict = NULL;
-      FT_ULong   priv_len  = 0;


+      parser->private_len = 0;
       for (;;)
       {
         error = read_pfb_tag( stream, &tag, &size );
         if ( error )
           goto Fail;

-        if ( tag != 0x8002U )
+        if ( tag != 0x8002U || !size )
           break;

-        if ( FT_QREALLOC( priv_dict, priv_len, priv_len + size ) ||
-             FT_STREAM_READ( priv_dict + priv_len, size )        )
-          goto Fail;
+        parser->private_len += size;

-        priv_len += size;
+        if ( FT_STREAM_SKIP( size ) )
+          goto Fail;
       }

       /* Check that we have a private dictionary there */
-      if ( priv_len == 0 )
+      if ( parser->private_len == 0 )
       {
         FT_ERROR(( "T1_Get_Private_Dict:"
                    " invalid private dictionary section\n" ));
@@ -300,8 +301,26 @@
         goto Fail;
       }

-      parser->private_dict = priv_dict;
-      parser->private_len  = priv_len;
+      if ( FT_STREAM_SEEK( start_pos )                            ||
+           FT_QALLOC( parser->private_dict, parser->private_len ) )
+        goto Fail;
+
+      parser->private_len = 0;
+      for (;;)
+      {
+        error = read_pfb_tag( stream, &tag, &size );
+        if ( error || tag != 0x8002U )
+        {
+          error = FT_Err_Ok;
+          break;
+        }
+
+        if ( FT_STREAM_READ( parser->private_dict + parser->private_len,
+                             size ) )
+          goto Fail;
+
+        parser->private_len += size;
+      }
     }
     else
     {
